/** An icon as markup. `size` in px (default 20); the stroke follows the text colour. */
export function icon(name, { size = 20, label = '' } = {}) {
  const body = ICONS[name] || ICONS.help;
  const a11y = label ? `role="img" aria-label="${esc(label)}"` : 'aria-hidden="true"';
  return raw(`<svg class="k-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" ${a11y}>${body}</svg>`);
}

/** Add (or replace) icons: addIcons({ custom: '<path d="..."/>' }). */
export function addIcons(map) { Object.assign(ICONS, map); }

export const hasIcon = (name) => Object.prototype.hasOwnProperty.call(ICONS, name);
